-- The year's clock records, from the Hik-Connect timesheet export.
--
-- One thousand nine hundred and eighty-four days of in-and-out, turned into
-- four thousand and twenty-three punches. Stored as punches rather than as
-- finished verdicts on purpose: every rule in this app reads punches, so a
-- January day and a September day are then worked out by exactly the same code,
-- and a shift corrected next month corrects January with it.
--
-- Which is also what makes the absences appear without being written anywhere.
-- A rostered day with no punch already computes as absent — that is the rule,
-- not an import artefact — so loading the rota and the clock records is the
-- whole job. Nothing needs to declare anybody absent.
--
-- A clock-out earlier than its clock-in belongs to the next morning, and is
-- dated accordingly. The shift window puts it back with the evening it belongs
-- to; that is the same path a live overnight punch takes.
--
-- Recorded under the serial IMPORT rather than the terminal's own, so the
-- Terminals screen keeps counting what the terminal actually sent, and so these
-- can be told apart from live data for ever.
--
-- The guard matters: the terminal has been uploading its own backlog since its
-- listening host was switched on, and those days must win. Any day that already
-- has a punch from a real device is skipped whole — never half-imported, which
-- would leave a clock-in from one source and a clock-out from another.

CREATE TABLE _imp_punch (
  employee_no TEXT NOT NULL, work_day TEXT NOT NULL, at_local TEXT NOT NULL,
  day TEXT NOT NULL, direction TEXT NOT NULL
);




































INSERT OR IGNORE INTO att_punches
  (device_serial, employee_no, staff_id, at_utc, at_local, day, direction, source, dedupe_key)
  SELECT 'IMPORT', i.employee_no, s.id, i.at_local, i.at_local, i.day, i.direction, 'import',
         'imp:' || i.employee_no || ':' || i.at_local || ':' || i.direction
    FROM _imp_punch i
    JOIN att_staff s ON s.employee_no = i.employee_no
   WHERE NOT EXISTS (
     SELECT 1 FROM att_punches p
      WHERE p.employee_no = i.employee_no AND p.day = i.work_day AND p.device_serial <> 'IMPORT');

DROP TABLE _imp_punch;
